D=Path(__file__).resolve().parent
P=D.parent
ROOT=P.parent.parent
OLD=P.parent/'flat132-hand-fit-2026-10-19'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def js(v):return json.dumps(v,separators=(',',':'),ensure_ascii=False)
def arr(v):return np.round(v,5).tolist()
def trace(m,name,color,opacity=1):
 v,f=m.vertices,m.faces
 return dict(type='mesh3d',name=name,x=arr(v[:,0]),y=arr(v[:,1]),z=arr(v[:,2]),i=f[:,0].tolist(),j=f[:,1].tolist(),k=f[:,2].tolist(),color=color,opacity=opacity,flatshading=False,showlegend=False,text=name,hovertemplate='%{text}<br>X %{x:.2f} · Y %{y:.2f} · Z %{z:.2f} mm<extra></extra>',lighting=dict(ambient=.65,diffuse=.8,specular=.25,roughness=.65,fresnel=.03),lightposition=dict(x=200,y=-100,z=200))
def group(ref):
 if ref=='H01':return 'sensor'
 if ref in ('H02','H20'):return 'force'
 if ref in ('H12','H23') or ref.startswith(('H24','H25')):return 'retention'
 if ref=='P05':return 'yoke'
 if ref in ('P01','P060','P061','P070a','P070b','P071a','P071b'):return 'frame'
 if ref in ('P02','P03'):return 'palm'
 if ref=='P04':return 'grip'
 if ref in ('P08','P09','P10'):return 'enclosure'
 if ref in ('H030','H031'):return 'springs'
 if ref in ('H11','H13','H15','H160','H161','H170','H171','H180','H181','H21','H22'):return 'adjustment'
 return 'hardware'
COLORS=dict(sensor='#de753d',force='#205e86',retention='#7d8b96',yoke='#4a8abf',frame='#25888a',palm='#7a78ad',grip='#dfab58',enclosure='#65778b',springs='#9aa8b4',hardware='#8b99a2',adjustment='#8b99a2',hand='#d6ac93')
